import pytest
from popsim.tests.fixtures import cmod_test_dataset, reduced_cmod_test_dataset
from popsim.ml.dataloading import make_time_dep_dataloader, make_time_indep_dataloader, XarrayPreppedDataset, DEFAULT_SAMPLE_DIM
import numpy as np
from copy import deepcopy
import xarray as xr
from popsim.ml._types import TrainingMetadata

def _run_dl_checks(dl, batch_size, expected_n_samps, shuffle, segment_length, convert_xr):
    """Generic function to check the properties of a dataloader generated by make_time_dep_dataloader and make_time_indep_dataloader."""
    # "None" batch size should be equivalent to loading all samples in a single batch.
    batch_size_handle_none = batch_size if batch_size is not None else expected_n_samps

    # The number of batches should be the number of samples divided by the batch size rounded up.
    expected_n_batches = max(1, np.ceil(expected_n_samps / batch_size_handle_none).astype(int))
    assert len(dl) == expected_n_batches

    # For each batch, check it is an XarrayPreppedDataset and that the sizes are correct.
    first_batches = []
    for idx, batch in enumerate(dl):
        assert isinstance(batch, XarrayPreppedDataset)

        # Make sure the leading dimension is the sample dimension.
        assert list(batch.ds.dims.keys())[0] == DEFAULT_SAMPLE_DIM

        # Nominally, the batch size is just "batch_size_handle_none", but the last batch may be smaller.
        expected_sample_size = min(batch_size_handle_none, expected_n_samps - idx * batch_size_handle_none)

        if segment_length is not None:
            assert dict(batch.ds.sizes) == {DEFAULT_SAMPLE_DIM: expected_sample_size, 'time_slice_input': segment_length}
        else:
            assert batch.ds.sizes[DEFAULT_SAMPLE_DIM] == expected_sample_size

        inputs, targets = batch.get_inputs_and_targets()

        if convert_xr:
            assert isinstance(targets, dict)
        else:
            assert isinstance(targets, xr.Dataset)
        
        first_batches.append(deepcopy(batch))

    # Iterate through the dataloader again to check that the "shuffle" flag works as intended.
    second_round_batches = [batch for batch in dl]

    if shuffle:
        assert first_batches != second_round_batches
    else:
        assert first_batches == second_round_batches

@pytest.mark.parametrize("segmenting_case", [{"seg_length": 250, "seg_overlap": 25, "expected_n_samps" : 724}, {"seg_length": 250, "seg_overlap": 0, "expected_n_samps" : 655},
                                             {"seg_length": None, "seg_overlap": 0, "expected_n_samps" : 99}])
@pytest.mark.parametrize("batch_size", [None, 1, 64, 1024, np.iinfo(np.int32).max])
@pytest.mark.parametrize("shuffle", [True, False])
@pytest.mark.parametrize("convert_xr_to_jnp", [True, False])
def test_make_time_dep_dataloader(reduced_cmod_test_dataset, segmenting_case, batch_size, shuffle, convert_xr_to_jnp):
    ds, state_init_vars, input_vars, target_vars = reduced_cmod_test_dataset

    # expected_n_samps were determined by manually checking the dataset.
    segment_length, segment_overlap, expected_n_samps = segmenting_case["seg_length"], segmenting_case["seg_overlap"], segmenting_case["expected_n_samps"]
    dl = make_time_dep_dataloader(
        ds=ds,
        time_coord="time",
        episode_coord="shot",
        state_init_vars=state_init_vars,
        input_vars=input_vars,
        target_vars=target_vars,
        convert_xr_to_jnp=convert_xr_to_jnp,
        segment_length=segment_length,
        segment_overlap=segment_overlap,
        batch_size=batch_size,
        shuffle=shuffle
    )

    _run_dl_checks(
        dl=dl, 
        batch_size=batch_size, 
        expected_n_samps=expected_n_samps, 
        shuffle=shuffle,
        segment_length=segment_length,
        convert_xr=convert_xr_to_jnp
    )

@pytest.mark.parametrize("batch_size", [None, 1024, np.iinfo(np.int32).max])
@pytest.mark.parametrize("shuffle", [True, False])
@pytest.mark.parametrize("convert_xr_to_jnp", [True, False])
def test_make_time_indep_dataloader(reduced_cmod_test_dataset, batch_size, shuffle, convert_xr_to_jnp):
    ds, _, _, _ = reduced_cmod_test_dataset
    expected_n_samps = 151046 # Manually checked the dataset.
    dl = make_time_indep_dataloader(
        ds=ds,
        time_coord="time",
        episode_coord="shot",
        input_vars=["p_rad", "ip", "n_e"],
        target_vars=["Wmhd"],
        convert_xr_to_jnp=convert_xr_to_jnp,
        batch_size=batch_size,
        shuffle=shuffle
    )

    _run_dl_checks(
        dl=dl, 
        batch_size=batch_size, 
        expected_n_samps=expected_n_samps, 
        shuffle=shuffle,
        segment_length=None,
        convert_xr=convert_xr_to_jnp
    )

def test_prepped_ds_error(reduced_cmod_test_dataset):
    """Test that assigning the wrong sample coordinate to the TrainingMetadata raises an error."""
    ds, _, _, _ = reduced_cmod_test_dataset

    data_var_names = list(ds.data_vars.keys())

    train_meta = TrainingMetadata(
        convert_xr_to_jnp=False,
        sample_coord=data_var_names[0], # Data vars are 2D, so this should create an error.
        sample_dim="shot",
        input_vars=data_var_names[:2],
        target_vars=data_var_names[2:4],
        time_dep_metadata=TrainingMetadata.TimeDepMetadata(
            state_init_vars=data_var_names[4:],
            time_coord="time",
            time_dim="time",
        )
    )


    with pytest.raises(ValueError):
        dataset = XarrayPreppedDataset(ds, train_meta)

@pytest.mark.parametrize("batch_size", [1024])
@pytest.mark.parametrize("time_dependent", [True])
def test_dl_limit_dim(reduced_cmod_test_dataset, batch_size, time_dependent):
    """Tests for limiting dimensions in the dataloader"""
    ds, state_init_vars, input_vars, target_vars = reduced_cmod_test_dataset

    convert_xr = True
    shuffle = True

    if time_dependent:
        dl = make_time_dep_dataloader(
            ds=ds,
            time_coord="time",
            episode_coord="shot",
            state_init_vars=state_init_vars,
            input_vars=input_vars,
            target_vars=target_vars,
            batch_size=batch_size,
            convert_xr_to_jnp=convert_xr,
            shuffle=shuffle
        )
    else:
        dl = make_time_indep_dataloader(
            ds=ds,
            time_coord="time",
            episode_coord="shot",
            input_vars=input_vars,
            target_vars=target_vars,
            batch_size=batch_size,
            convert_xr_to_jnp=convert_xr,
            shuffle=shuffle
        )

    # Check that we can't limit by dimensions that don't exist
    with pytest.raises(ValueError):
        dl.limit_size(size=10, episode_coord="non_existent_coord")

    # Check that we can limit by all dimensions from the original dataset
    for dim in ds.dims.keys():
        lim_dl = dl.limit_dim(size=10, dim=dim)
        _run_dl_checks(lim_dl, batch_size=batch_size, expected_n_samps=10, shuffle=shuffle, segment_length=None, convert_xr=convert_xr)

    if time_dependent:
        # Check that we can limit by the time segment dimension
        lim_dl = dl.limit_dim(size=10, dim="time_slice_input")
        _run_dl_checks(lim_dl, batch_size=batch_size, expected_n_samps=10, shuffle=shuffle, segment_length=None, convert_xr=convert_xr)
